#include <cstdio>
int main(void) {
    int sum = 0;
    int i;
    for (i = 0; i < 100; i++) {
        if (i % 2 == 0) {
            continue;
        }
        if (sum > 20) {
            break;
        }
        sum += i;
    }
    int k = 0;
    do {
        k += 3;
    } while (k < 10);
    printf("sum=%d i=%d k=%d\n", sum, i, k); // CHECK
    return 0;
}
